Lemma dobj_cfg_pre : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
       (F : bvmap 5 word) fc (m : mem) (AT p allocb lo shi : Z),
  ro_cells asegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= shi -> AT mod 8 = 0 ->
  ro_cells asegs m p [C8 (wz AVP_CONFIG_SVC)] -> 0 < p -> p mod 8 = 0 -> p + 8 <= aceil -> accessible m p 8 ->
  0 <= allocb < 2^64 ->
  AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m -> stack0 m lo shi ->
  evt asegs (fun ms' => exists a1 a2 m',
      ms' = MS (mkR (Z_to_bv 64 (P_A_DEALLOC_OBJ_CONFIG + 0x68)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (Z_to_bv 64 p) (Z_to_bv 64 allocb)
                    (Z_to_bv 64 p) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 2147450880) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc (Z_to_bv 64 (P_A_DEALLOC_OBJ_CONFIG + 0x68))) fc None m' (seg_rom asegs)
      /\ munch [(bv_unsigned sp + -32, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ stk asegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells asegs m' (bv_unsigned sp + -32) (dobj_frame s2 s1 s0 ra))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 p) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_DEALLOC_OBJ_CONFIG) fc None m (seg_rom asegs)).
Proof.
  intros until shi. intros HAT SPA ATS AT8 HP P0 P8 PHI ACP ALR XS ST LO CEIL MI AC SK.
  eapply evt_cut.
  { eapply (dobj_segA P_A_DEALLOC_OBJ_CONFIG ltac:(left; reflexivity)) with (AT := AT) (p := p) (allocb := allocb) (lo := lo) (shi := shi); fast_eassumption. }
  intros ms' (a1v & a2v & m1 & -> & MU & WM & MI1 & ST1 & FR1).
  eapply evt_mono.
  { pose proof noncopyable_dtor_spec as RS. unfold ret_stmt in RS. unfold dobj_dtor. cbn [Z.eqb Pos.eqb P_A_DEALLOC_OBJ_CONFIG]. eapply RS. exact MI1. }
  intros ms'' [-> _]. do 3 eexists. split; [reflexivity|]. repeat (split; [fast_eassumption|]). exact FR1.
Qed.

