  (* [comment removed for export] *)
  Lemma dobj_assemble : forall T size, dobj_tail_ok T size ->
    forall (pcv rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (s2v s1v s0v rav : word)
           (F : bvmap 5 word) (fc : bv 32) (msF1 : machine_state) (m m1 : mem) (mo mo1 : Model)
           (s : as_St H) (LB : list block) (LF : list fframe) (bp : bptr) (p allocb lo B shi : Z) (errv : word)
           (body : list cell) (j7 : list byte),
      as_VIS H s msF1 = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (Z_to_bv 64 p) (Z_to_bv 64 allocb)
                               a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 2147450880) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F pcv fc None m1 (seg_rom asegs) ->
      (pcv = Z_to_bv 64 T \/ pcv = ret_pc (Z_to_bv 64 T)) ->
      munch [(bv_unsigned sp + -32, bv_unsigned sp)]%Z m m1 -> wmono asegs m m1 -> mem_inv asegs m1 ->
      stk asegs m1 lo (bv_unsigned sp + -32) ->
      rw_cells asegs m1 (bv_unsigned sp + -32) (dobj_frame s2v s1v s0v rav) ->
      as_AKREL H s (mkCfg msF1 mo1) -> as_MPRES H mo mo1 ->
      In (bp, p, size + 15) LB ->
      rw_cells asegs m p (body ++ CookieCells j7) -> Z.of_nat (cells_size body) = size -> addressable m p (size + 15) ->
      AAllocImpl LB m allocb -> AXStatics2 m ->
      as_RHEAP H s LB m ->
      as_rauxv_ok H m B -> bv_unsigned sp <= B ->
      aceil <= lo -> lo <= bv_unsigned sp - ADOBJ_STACK ->
      rw_cells asegs m (errno_addr tp) [C4 errv] -> tp = Z_to_bv 64 ATP ->
      bv_unsigned rav mod 2 = 0 ->
      bv_unsigned sp mod 16 = 0 ->
      as_RFS H LF m -> ACONST m -> stack0 m lo shi ->
      as_Cf H (size + 15) <= as_AL H s ->
      as_SR H (dealloc_obj_post H rav sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF p (size + 15) allocb lo B shi errv m mo)
        (mkCfg msF1 mo1).
  Proof.
    intros T size HT. intros until j7. intros VIS1 PC MU WM MI1 ST1 FR1 KREL1 MP1 IN BLK SZ ADB AI XS HP AUX SPB CEIL LO ERR TP RA SP16 RF AC SK COST.
    unfold ADOBJ_STACK, ADEALLOCATE_STACK, AFREE_STACK in LO. pose proof aceil_facts as (AF1 & AF2 & AF3).
    pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
    pose proof (ah_blocks H HH _ _ _ _ HP IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn [blk_addr blk_size fst snd] in R1, R2, R3, R4, R5, R6, R7.
    assert (EA : errno_addr (Z_to_bv 64 ATP) = AERRNO) by (unfold AERRNO, ATP; rewrite unsigned_lit; lia).
    destruct (seg_stack_bundle H HH s LB LF B m m1 _ _ lo shi HP RF AC AUX SK MU WM ltac:(lia)) as (HP1 & RF1 & AC1 & AUX1 & SK1).
    assert (BLK1 : rw_cells asegs m1 p (body ++ CookieCells j7)).
