    split; [eapply (ah_mpres_trans H HH); [exact MP1| exact MP2]|].
    split; [exact MI2|]. split; [exact ST2|]. split; [exact ERR2|]. split; [exact AUX2|]. split; [exact IN|]. split; [exact HEAP2|].
