    split. { eapply (apres_trans H); [| exact RP2]. eapply (seg_stack_apres H HH); [exact HEAP2| exact MU| exact WM| lia| lia]. }
    split; [exact RF2|]. split; [exact AC2|]. split; [exact SK2| exact AL2].
